export interface PinmapInput {
  readonly map: PinMap;
  readonly mcu: StMcu;
}

function checkMcuConfig(spec: CircuitSpec, ctx: BuildContext): PartLabel | null {
  if (spec.mcu === null && ctx.pinmap !== null) throw new Error("a pin map was given but the circuit names no MCU");
  if (spec.mcu === null) return null;
  if (ctx.pinmap === null) throw new Error(`circuit names MCU ${spec.mcu.label} but no pin map was given`);
  const label = spec.mcu.label;
  if (!spec.parts.some((p) => p.label === label)) throw new Error(`circuit names MCU ${label}, which is not a part`);
  return label;
}

if (isMcu && ctx.pinmap !== null) {
  const { map, mcu } = ctx.pinmap;
  for (const a of map.assignments) {
    const st = mcu.pins.get(a.pin);
    if (st === undefined) throw new Error(`pin map assigns ${a.pin}, which ${mcu.refName} does not have; run pnpm pinmap validate`);
    const prior = declared.get(st.position);
    if (prior !== undefined) {
      const where = prior.net === null ? "as not connected" : `on net ${prior.net}`;
      throw new Error(
        `${p.label} pin ${st.position} (${a.pin}) is declared in the circuit ${where} and assigned by the pin map to ${a.net}; ` +
          "pinmap.json is authoritative for MCU pins — remove it from the circuit",
      );
    }
    declared.set(st.position, { part: p.label, pin: st.position, unit: unitFor(st.position), identity: a.pin, net: a.net, origin: "pinmap" });
  }
}
